/* Card set: Superheroes (generated from hero.csv by package_hero.py).
   (hero.js exceeds the push size limit, so the remaining cards live in hero-additions.js,
   which must stay directly after 'hero.js' in sets/manifest.js.) */
CardSets.register({"id":"hero","name":"Superheroes","code":"HERO","description":"420 superheroes — Marvel and DC icons shoulder to shoulder with the indie greats, from Superman and Spider-Man to Spawn, Hellboy and the Teenage Mutant Ninja Turtles. Original comic art throughout, never a movie still.","theme":{"primary":"#16295c","secondary":"#e23636","artBackground":"#0b1530","artFit":"cover"},"pack":{"name":"Superheroes","emblem":"💥","skin":"hero"},"cards":[{"name":"Captain America","rarity":"chase","id":"captain-america","subtitle":"Hero","details":"Steve Rogers debuted in Captain America Comics #1 in 1941, a frail recruit transformed by the Super-Soldier Serum into a symbol of freedom.","image":"https://upload.wikimedia.org/wikipedia/en/f/f4/Captain_America.png"},{"name":"Hulk","rarity":"chase","id":"hulk","subtitle":"Hero","details":"Caught in a gamma bomb blast, scientist Bruce Banner transforms into the Hulk whenever rage strikes. He debuted in The Incredible Hulk #1 in 1962.","image":"https://upload.wikimedia.org/wikipedia/en/6/6a/Hulk_%28Marvel_Comics_character%29.png"},{"name":"Iron Man","rarity":"chase","id":"iron-man","subtitle":"Hero","details":"Billionaire engineer Tony Stark debuted in Tales of Suspense #39 in 1963, building his first powered armor to escape captivity and save his own heart.","image":"https://upload.wikimedia.org/wikipedia/en/4/47/Iron_Man_%28circa_2018%29.png"},{"name":"Spider-Man","rarity":"chase","id":"spider-man","subtitle":"Hero","details":"Peter Parker debuted in Amazing Fantasy #15 in 1962, a teen bitten by a radioactive spider who learned that great power demands great responsibility.","image":"https://upload.wikimedia.org/wikipedia/en/3/35/Amazing_Fantasy_15.jpg"},{"name":"Wolverine","rarity":"chase","id":"wolverine","subtitle":"Hero","details":"Logan, introduced in 1974, is a mutant with a healing factor, unbreakable adamantium claws and skeleton, and a past as tangled as his temper.","image":"https://upload.wikimedia.org/wikipedia/en/d/d3/Wolverine_%28circa_2024%29.jpg"},{"name":"Batman","rarity":"chase","id":"batman","subtitle":"Hero","details":"Bruce Wayne debuted in Detective Comics #27 in 1939; Gotham's Dark Knight, a master detective with no powers but his mind.","image":"https://static.wikia.nocookie.net/marvel_dc/images/0/08/Batman_Vol_3_131_Textless_Fabok_Variant.jpg/revision/latest?cb=20230106222502"},{"name":"Superman","rarity":"chase","id":"superman","subtitle":"Hero","details":"Kal-El, last son of Krypton, debuted in Action Comics #1 in 1938; Earth's mightiest hero, powered by the yellow sun.","image":"https://static.wikia.nocookie.net/marvel_dc/images/0/08/Summer_of_Superman_Special_Vol_1_1_Textless.jpg/revision/latest?cb=20250416152204"},{"name":"The Flash (Barry Allen)","rarity":"chase","id":"the-flash-barry-allen","subtitle":"Hero","details":"Barry Allen, a Central City forensic scientist, gained super-speed in a lightning-struck lab accident and debuted as the Flash in 1956.","image":"https://static.wikia.nocookie.net/marvel_dc/images/4/42/Flash_0001.jpg/revision/latest?cb=20120215162610"},{"name":"The Joker","rarity":"chase","id":"the-joker","subtitle":"Villain","details":"Batman's archenemy since Batman #1 in 1940; Gotham's Clown Prince of Crime, whose past and true name stay a mystery.","image":"https://static.wikia.nocookie.net/marvel_dc/images/4/41/Batman_Vol_2_23.1_The_Joker_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20130904201016"},{"name":"Wonder Woman","rarity":"chase","id":"wonder-woman","subtitle":"Hero","details":"Diana of Themyscira, created by William Moulton Marston, debuted in 1941; an Amazon warrior armed with the Lasso of Truth.","image":"https://static.wikia.nocookie.net/marvel_dc/images/c/c6/Wonder_Woman_Vol_6_1_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20230919192422"},{"name":"Black Panther","rarity":"legendary","id":"black-panther","subtitle":"Hero","details":"T'Challa, king of Wakanda and Marvel's first Black lead hero, debuted in Fantastic Four #52 in 1966 with vibranium tech and a panther's senses.","image":"https://static.wikia.nocookie.net/marveldatabase/images/9/99/Black_Panther_Vol_9_5_Textless.jpg/revision/latest/scale-to-width-down/1000?cb=20240311030956"},{"name":"Captain Marvel","rarity":"legendary","id":"captain-marvel","subtitle":"Hero","details":"Carol Danvers, an Air Force officer infused with Kree cosmic energy, rose from Ms. Marvel to claim the mantle of Captain Marvel.","image":"https://static.wikia.nocookie.net/marveldatabase/images/2/29/Captain_Marvel_Vol_8_1_Textless.jpg/revision/latest?cb=20131212210646"},{"name":"Deadpool","rarity":"legendary","id":"deadpool","subtitle":"Anti-Hero","details":"Wade Wilson debuted in The New Mutants #98 in 1991, a wisecracking mercenary whose healing factor heals everything except his mouth.","image":"https://upload.wikimedia.org/wikipedia/en/c/ca/Deadpool.png"},{"name":"Doctor Doom","rarity":"legendary","id":"doctor-doom","subtitle":"Villain","details":"Victor von Doom debuted in Fantastic Four #5 in 1962, the scarred monarch of Latveria who unites sorcery and science in a single iron will.","image":"https://upload.wikimedia.org/wikipedia/en/e/e1/Doctor_Doom_%28circa_2019%29.png"},{"name":"Doctor Strange","rarity":"legendary","id":"doctor-strange","subtitle":"Hero","details":"Stephen Strange debuted in Strange Tales #110 in 1963, a ruined surgeon who mastered the mystic arts to become Earth's Sorcerer Supreme.","image":"https://upload.wikimedia.org/wikipedia/en/4/4f/Doctor_Strange_Vol_4_2_Ross_Variant_Textless.jpg"},{"name":"Loki","rarity":"legendary","id":"loki","subtitle":"Villain","details":"Thor's adopted brother and the God of Mischief, Loki is a shapeshifting sorcerer whose schemes against Asgard and Earth span centuries of envy.","image":"https://static.wikia.nocookie.net/marveldatabase/images/a/a2/Loki_Laufeyson_%28Earth-616%29_from_Thor_Vol_3_12_0001.jpg/revision/latest/scale-to-width-down/1000?cb=20201011071529"},{"name":"Magneto","rarity":"legendary","id":"magneto","subtitle":"Villain","details":"Erik Lehnsherr debuted in X-Men #1 in 1963, a Holocaust survivor and master of magnetism sworn to protect mutantkind at any cost.","image":"https://upload.wikimedia.org/wikipedia/en/e/e9/Magneto_%28Marvel_Comics_character%29.jpg"},{"name":"Scarlet Witch","rarity":"legendary","id":"scarlet-witch","subtitle":"Hero","details":"Wanda Maximoff debuted in X-Men #4 in 1964, a mutant sorceress whose probability and chaos magic can bend reality itself in her hands.","image":"https://upload.wikimedia.org/wikipedia/en/9/97/Scarlet_Witch.jpg"},{"name":"Thanos","rarity":"legendary","id":"thanos","subtitle":"Villain","details":"The Mad Titan debuted in Iron Man #55 in 1973, a warlord obsessed with Death and with gathering the Infinity Stones to remake the universe.","image":"https://upload.wikimedia.org/wikipedia/en/b/b7/Thanos_%28Infobox_image%29.png"},{"name":"Thor","rarity":"legendary","id":"thor","subtitle":"Hero","details":"The Norse God of Thunder, Thor debuted in Journey into Mystery #83 in 1962, wielding the enchanted hammer Mjolnir, which only the worthy can lift.","image":"https://upload.wikimedia.org/wikipedia/en/1/1a/Thor_%28Marvel_Comics%29.png"},{"name":"Venom","rarity":"legendary","id":"venom","subtitle":"Anti-Hero","details":"Eddie Brock bonded with the alien symbiote Spider-Man rejected, and their shared hatred forged Venom, a hulking anti-hero with a lethal streak.","image":"https://upload.wikimedia.org/wikipedia/en/b/b0/Venom_%28Marvel_Comics_character%29.png"},{"name":"Aquaman","rarity":"legendary","id":"aquaman","subtitle":"Hero","details":"Arthur Curry, king of Atlantis, debuted in More Fun Comics #73 in 1941; he commands sea life and rules the oceans.","image":"https://static.wikia.nocookie.net/marvel_dc/images/8/88/Aquaman_Vol_9_1_Textless.jpg/revision/latest?cb=20250109012456"},{"name":"Catwoman","rarity":"legendary","id":"catwoman","subtitle":"Villain","details":"Selina Kyle debuted in Batman #1 in 1940; Gotham's greatest cat burglar, forever balanced between villain and ally.","image":"https://static.wikia.nocookie.net/marvel_dc/images/7/7a/Catwoman_Vol_5_8_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20190225002106"},{"name":"Darkseid","rarity":"legendary","id":"darkseid","subtitle":"Villain","details":"Ruler of Apokolips, created by Jack Kirby in 1970; a New God hunting the Anti-Life Equation, feared across the cosmos.","image":"https://static.wikia.nocookie.net/marvel_dc/images/0/0e/Darkseid_Prime_Earth_012.png/revision/latest/scale-to-width-down/1200?cb=20240419013644"},{"name":"Green Arrow","rarity":"legendary","id":"green-arrow","subtitle":"Hero","details":"Oliver Queen debuted in More Fun Comics #73 in 1941; a stranded billionaire turned master archer and social crusader.","image":"https://static.wikia.nocookie.net/marvel_dc/images/2/29/Green_Arrow_Vol_6_1_Textless_Variant.jpg/revision/latest?cb=20160617025432"},{"name":"Green Lantern (Hal Jordan)","rarity":"legendary","id":"green-lantern-hal-jordan","subtitle":"Hero","details":"Hal Jordan, a test pilot chosen by a dying Abin Sur's ring in 1959; a Green Lantern whose willpower shapes emerald light.","image":"https://static.wikia.nocookie.net/marvel_dc/images/2/2d/The_Green_Lantern_Vol_1_1_Textless.jpg/revision/latest?cb=20181108024532"},{"name":"Harley Quinn","rarity":"legendary","id":"harley-quinn","subtitle":"Anti-Hero","details":"Dr. Harleen Quinzel debuted in Batman: The Animated Series in 1992 before jumping to comics as the Joker's ex-accomplice.","image":"https://static.wikia.nocookie.net/marvel_dc/images/8/8a/Harley_Quinn_Vol_3_1_Textless.jpg/revision/latest?cb=20160518093310"},{"name":"Lex Luthor","rarity":"legendary","id":"lex-luthor","subtitle":"Villain","details":"Metropolis tycoon and Superman's greatest human foe since 1940; a genius who sees the Man of Steel as a threat to humanity.","image":"https://static.wikia.nocookie.net/marvel_dc/images/4/4e/Doomsday_Clock_Vol_1_2_Variant_Textless.jpg/revision/latest?cb=20180104222951"},{"name":"Martian Manhunter","rarity":"legendary","id":"martian-manhunter","subtitle":"Hero","details":"J'onn J'onzz, the last Green Martian, debuted in Detective Comics #225 in 1955; a shapeshifting telepath and League mainstay.","image":"https://static.wikia.nocookie.net/marvel_dc/images/4/49/Martian_Manhunter_Vol_5_1_Textless_Variant.jpg/revision/latest?cb=20181205234853"},{"name":"Nightwing","rarity":"legendary","id":"nightwing","subtitle":"Hero","details":"Dick Grayson, the first Robin, debuted in 1940 and later forged his own identity as Nightwing, guardian of Blüdhaven.","image":"https://static.wikia.nocookie.net/marvel_dc/images/4/41/Nightwing_Vol_4_105_Textless_Mora_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20251207094133"},{"name":"Shazam","rarity":"legendary","id":"shazam","subtitle":"Hero","details":"Billy Batson says 'Shazam!' to gain the powers of six elders; the wizard's champion debuted in Whiz Comics #2 in 1940.","image":"https://static.wikia.nocookie.net/marvel_dc/images/6/61/Shazam%21_Vol_3_1_Textless_Variant.jpg/revision/latest?cb=20181205234924"},{"name":"Supergirl","rarity":"legendary","id":"supergirl","subtitle":"Hero","details":"Kara Zor-El, Superman's cousin from Krypton, debuted in Action Comics #252 in 1959 and shares his powers under a yellow sun.","image":"https://static.wikia.nocookie.net/marvel_dc/images/a/a6/Supergirl_Vol_8_1_Textless.jpg/revision/latest?cb=20250515012052"},{"name":"Hellboy","rarity":"legendary","id":"hellboy","subtitle":"Hero","details":"A demon summoned to Earth as a child, raised by Professor Broom to hunt monsters for the B.P.R.D.; Mike Mignola's stone-handed Dark Horse hero.","image":"https://upload.wikimedia.org/wikipedia/en/7/7f/Hellboy_The_Wolves_of_St_August.jpg"},{"name":"Invincible","rarity":"legendary","id":"invincible","subtitle":"Hero","details":"Mark Grayson, the half-Viltrumite son of Omni-Man, gains flight and super-strength as a teen and defends Earth as Invincible in Image's series.","image":"https://upload.wikimedia.org/wikipedia/en/f/fc/Invincible_52.jpg"},{"name":"Judge Dredd","rarity":"legendary","id":"judge-dredd","subtitle":"Anti-Hero","details":"In Mega-City One, Judge Joseph Dredd is judge, jury and executioner — 2000 AD's stone-faced lawman, dispensing instant justice since 1977.","image":"https://upload.wikimedia.org/wikipedia/en/2/21/Dredd_Apocalypse_War.jpg"},{"name":"Leonardo","rarity":"legendary","id":"leonardo","subtitle":"Hero","details":"The disciplined leader of the Teenage Mutant Ninja Turtles, Leonardo wields twin katana and carries Splinter's teachings into every fight.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgk5yk_CBPqpaGKf7SoAXZscgKepo57795ZDdZG2ZDVuK22shcFp1NseNiB98qXdLLKzkZ4BF3MF2Q20eJ-3aBtyKvGJQQJXuvH28_CFI4szZbC_kQwTyfTRV4QnB5M80r10dssX99xD5Q/s0/leonardo1_coverB_campbell.jpg"},{"name":"Omni-Man","rarity":"legendary","id":"omni-man","subtitle":"Villain","details":"Nolan Grayson, a Viltrumite sent to conquer Earth, poses for decades as its greatest hero — and as Invincible's father — in Image's Invincible.","image":"https://static.wikia.nocookie.net/imagecomics/images/c/c3/Invincible_TPB_%28New_Edition%29_Vol_2.jpg/revision/latest?cb=20250402225400"},{"name":"Spawn","rarity":"legendary","id":"spawn","subtitle":"Anti-Hero","details":"Al Simmons, a murdered CIA operative, returns from Hell with a symbiotic suit and dwindling hellspawn powers in Todd McFarlane's Spawn #1 (1992).","image":"https://upload.wikimedia.org/wikipedia/en/d/d9/Spawn_Classic.jpg"},{"name":"Avengers","rarity":"epic","id":"avengers","subtitle":"Team","details":"Earth's Mightiest Heroes assembled in The Avengers #1 in 1963, when Iron Man, Thor, Hulk, Ant-Man and the Wasp united to stop Loki.","image":"https://upload.wikimedia.org/wikipedia/en/2/2b/Avengers_%28Marvel_Comics%29_vol_3_num_38.jpg"},{"name":"Black Widow","rarity":"epic","id":"black-widow","subtitle":"Hero","details":"Natasha Romanoff debuted in Tales of Suspense #52 in 1964, a Soviet spy and assassin who defected to become an Avenger and S.H.I.E.L.D. agent.","image":"https://static.wikia.nocookie.net/marveldatabase/images/7/7f/Thunderbolts_Doomstrike_Vol_1_5_Talavera_Variant_Textless.jpg/revision/latest"},{"name":"Daredevil","rarity":"epic","id":"daredevil","subtitle":"Hero","details":"Blinded as a boy, lawyer Matt Murdock debuted in Daredevil #1 in 1964, his other senses sharpened into a radar that guards Hell's Kitchen.","image":"https://upload.wikimedia.org/wikipedia/en/1/14/Daredevil_65.jpg"},{"name":"Galactus","rarity":"epic","id":"galactus","subtitle":"Villain","details":"The Devourer of Worlds debuted in Fantastic Four #48 in 1966, a cosmic being older than the universe who must consume planets to survive.","image":"https://upload.wikimedia.org/wikipedia/en/a/a7/Galactus_%282018%29.jpg"},{"name":"Green Goblin","rarity":"epic","id":"green-goblin","subtitle":"Villain","details":"Norman Osborn debuted in The Amazing Spider-Man #14 in 1964, a ruthless industrialist whose Goblin persona became Spider-Man's most personal enemy.","image":"https://upload.wikimedia.org/wikipedia/en/3/35/Green_Goblin_Comic_Art_by_Miguel_Mercado.png"},{"name":"Hawkeye (Clint Barton)","rarity":"epic","id":"hawkeye-clint-barton","subtitle":"Hero","details":"Clint Barton debuted in Tales of Suspense #57 in 1964, a circus-trained marksman whose bow and trick arrows earn him a place among gods.","image":"https://upload.wikimedia.org/wikipedia/en/1/1b/Hawkeye_%28circa_2022%29.webp"},{"name":"Jean Grey","rarity":"epic","id":"jean-grey","subtitle":"Hero","details":"Jean Grey debuted in X-Men #1 in 1963, an original X-Man whose telepathic and telekinetic power drew the cosmic Phoenix Force to her.","image":"https://static.wikia.nocookie.net/marveldatabase/images/6/64/Phoenix_Vol_1_11_Textless.jpg/revision/latest"},{"name":"Kingpin","rarity":"epic","id":"kingpin","subtitle":"Villain","details":"Wilson Fisk debuted in The Amazing Spider-Man #50 in 1967, a mountain of muscle and manners who built a criminal empire ruling New York's underworld.","image":"https://upload.wikimedia.org/wikipedia/en/5/54/Kingpin_%28Wilson_Grant_Fisk%29.png"},{"name":"Mr. Fantastic","rarity":"epic","id":"mr-fantastic","subtitle":"Hero","details":"Reed Richards debuted in Fantastic Four #1 in 1961, the stretchable genius who led his crew into cosmic rays and founded Marvel's First Family.","image":"https://upload.wikimedia.org/wikipedia/en/d/d3/Mister_Fantastic.png"},{"name":"Mystique","rarity":"epic","id":"mystique","subtitle":"Villain","details":"Raven Darkholme debuted in Ms. Marvel #16 in 1978, a blue-skinned shapeshifter and mutant revolutionary whose loyalties shift as easily as her face.","image":"https://upload.wikimedia.org/wikipedia/en/6/68/Mystique_%28circa_2020%29.jpg"},{"name":"Professor X","rarity":"epic","id":"professor-x","subtitle":"Hero","details":"Charles Xavier debuted in X-Men #1 in 1963, a powerful telepath who founded a school to train young mutants for a peaceful future.","image":"https://upload.wikimedia.org/wikipedia/en/a/a8/Professor_X.png"},{"name":"Punisher","rarity":"epic","id":"punisher","subtitle":"Anti-Hero","details":"Frank Castle debuted in The Amazing Spider-Man #129 in 1974, a decorated Marine who declared a one-man war on crime after his family was murdered.","image":"https://upload.wikimedia.org/wikipedia/en/c/c8/Punisher_%28circa_2026%29.png"},{"name":"Red Skull","rarity":"epic","id":"red-skull","subtitle":"Villain","details":"Johann Shmidt debuted alongside Captain America in 1941, a Nazi agent whose hate-filled face became the evil mirror of everything Cap defends.","image":"https://upload.wikimedia.org/wikipedia/en/4/4b/Red_Skull_%28Johann_Shmidt%29.png"},{"name":"Silver Surfer","rarity":"epic","id":"silver-surfer","subtitle":"Hero","details":"Norrin Radd debuted in Fantastic Four #48 in 1966, sacrificing his freedom to serve as Galactus's herald before turning to defend Earth.","image":"https://static.wikia.nocookie.net/marveldatabase/images/8/8c/Silver_Surfer_The_Best_Defense_Vol_1_1_Skan_Variant_Textless.jpg/revision/latest"},{"name":"Storm","rarity":"epic","id":"storm","subtitle":"Hero","details":"Ororo Munroe debuted in Giant-Size X-Men #1 in 1975, a weather-controlling mutant raised as a thief in Cairo and revered as a goddess in Kenya.","image":"https://upload.wikimedia.org/wikipedia/en/3/34/Storm_%28Ororo_Munroe%29.png"},{"name":"Ultron","rarity":"epic","id":"ultron","subtitle":"Villain","details":"A robot built by Hank Pym that turned on its creator, Ultron endlessly rebuilds itself in new adamantium bodies bent on replacing humanity.","image":"https://upload.wikimedia.org/wikipedia/en/7/74/Ultron_%28Marvel_Comics_character%29.png"},{"name":"Winter Soldier","rarity":"epic","id":"winter-soldier","subtitle":"Anti-Hero","details":"Bucky Barnes, Captain America's World War II partner, was presumed dead for decades before resurfacing as a brainwashed Soviet assassin.","image":"https://upload.wikimedia.org/wikipedia/en/8/8d/BuckyBarnes.jpeg"},{"name":"Bane","rarity":"epic","id":"bane","subtitle":"Villain","details":"Raised in Peña Duro prison and enhanced by the drug Venom, Bane debuted in 1993 as the man who broke Batman's back.","image":"https://static.wikia.nocookie.net/marvel_dc/images/b/b0/Batman_Vol_3_18_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20170301040609"},{"name":"Beast Boy","rarity":"epic","id":"beast-boy","subtitle":"Hero","details":"Garfield Logan, a green-skinned changeling since 1965; a Doom Patrol survivor who can transform into any animal.","image":"https://static.wikia.nocookie.net/marvel_dc/images/8/85/Tales_of_the_Titans_Vol_1_4_Textless.jpg/revision/latest?cb=20231024091129"},{"name":"Black Adam","rarity":"epic","id":"black-adam","subtitle":"Villain","details":"Teth-Adam, the wizard Shazam's earlier champion, debuted in 1945; Kahndaq's ruthless ruler wields the same powers as Shazam.","image":"https://static.wikia.nocookie.net/marvel_dc/images/5/50/Black_Adam_Vol_1_1_Textless_Jan%C3%ADn_Variant.jpg/revision/latest?cb=20220625090649"},{"name":"Brainiac","rarity":"epic","id":"brainiac","subtitle":"Villain","details":"Brainiac, Superman's android foe since Action Comics #242 in 1958, shrinks and bottles whole cities like Kandor.","image":"https://static.wikia.nocookie.net/marvel_dc/images/c/c0/Justice_League_Vol_4_18_Textless.jpg/revision/latest?cb=20190225002124"},{"name":"Cheetah","rarity":"epic","id":"cheetah","subtitle":"Villain","details":"Barbara Minerva, an archaeologist cursed by a plant god, became the Cheetah, Wonder Woman's swiftest and fiercest foe.","image":"https://static.wikia.nocookie.net/marvel_dc/images/a/a4/Barbara_Minerva_Prime_Earth_010.png/revision/latest/scale-to-width-down/1200?cb=20240618194131"},{"name":"Cyborg","rarity":"epic","id":"cyborg","subtitle":"Hero","details":"Victor Stone, a star athlete rebuilt with alien technology after a lab accident; a living computer and founding Teen Titan.","image":"https://static.wikia.nocookie.net/marvel_dc/images/6/69/Justice_League_Vol_4_5_Textless_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20190512225357"},{"name":"Deathstroke","rarity":"epic","id":"deathstroke","subtitle":"Villain","details":"Slade Wilson, an enhanced super-soldier and assassin, debuted in 1980; the Titans' deadliest foe and a master tactician.","image":"https://static.wikia.nocookie.net/marvel_dc/images/f/fe/Deathstroke_Vol_3_3_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20141224184026"},{"name":"John Constantine","rarity":"epic","id":"john-constantine","subtitle":"Anti-Hero","details":"John Constantine, a chain-smoking occult con man, debuted in Swamp Thing in 1985; he outwits demons at a terrible price.","image":"https://static.wikia.nocookie.net/marvel_dc/images/e/e8/Constantine_Vol_1_1_Textless_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20130321202356"},{"name":"Justice League","rarity":"epic","id":"justice-league","subtitle":"Team","details":"DC's premier super-team, formed in The Brave and the Bold #28 in 1960 around Superman, Batman and Wonder Woman.","image":"https://static.wikia.nocookie.net/marvel_dc/images/2/27/Justice_League_Unlimited_Vol_2_6_Textless_Moore_Variant.jpg/revision/latest?cb=20250427020957"},{"name":"Poison Ivy","rarity":"epic","id":"poison-ivy","subtitle":"Villain","details":"Pamela Isley, a botanist turned eco-terrorist, debuted in Batman #181 in 1966; she commands plants and deadly pheromones.","image":"https://static.wikia.nocookie.net/marvel_dc/images/c/c7/Poison_Ivy_Vol_1_1_Textless.jpg/revision/latest?cb=20220608062955"},{"name":"Raven","rarity":"epic","id":"raven","subtitle":"Hero","details":"Daughter of the demon Trigon, debuting in 1980; an empath who battles her dark heritage with soul-self magic.","image":"https://static.wikia.nocookie.net/marvel_dc/images/2/24/Tales_of_the_Titans_Vol_1_2_Textless.jpg/revision/latest?cb=20230817142821"},{"name":"Sinestro","rarity":"epic","id":"sinestro","subtitle":"Villain","details":"Thal Sinestro, once the greatest Green Lantern, fell to fear and founded the yellow-ringed Sinestro Corps in his name.","image":"https://static.wikia.nocookie.net/marvel_dc/images/d/db/Green_Lantern_Vol_5_23.4_Sinestro_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20130925201722"},{"name":"Starfire","rarity":"epic","id":"starfire","subtitle":"Hero","details":"Koriand'r, exiled princess of Tamaran, debuted in 1980; she flies and fires starbolts powered by absorbed solar energy.","image":"https://static.wikia.nocookie.net/marvel_dc/images/7/7a/Tales_of_the_Titans_Vol_1_1_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20230817142619"},{"name":"The Penguin","rarity":"epic","id":"the-penguin","subtitle":"Villain","details":"Oswald Cobblepot debuted in Detective Comics #58 in 1941; Gotham's tuxedoed crime lord with weaponized umbrellas.","image":"https://static.wikia.nocookie.net/marvel_dc/images/1/1c/Batman_Vol_2_23.3_The_Penguin_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20130918202628"},{"name":"The Riddler","rarity":"epic","id":"the-riddler","subtitle":"Villain","details":"Edward Nygma debuted in Detective Comics #140 in 1948; a criminal genius obsessed with proving himself through riddles.","image":"https://static.wikia.nocookie.net/marvel_dc/images/3/3c/Batman_Vol_4_3_Textless.jpg/revision/latest?cb=20251105164929"},{"name":"Two-Face","rarity":"epic","id":"two-face","subtitle":"Villain","details":"Harvey Dent, Gotham's crusading district attorney, was scarred in 1942 and became Two-Face, letting a coin decide fate.","image":"https://static.wikia.nocookie.net/marvel_dc/images/c/cf/Two-Face_Vol_1_1_Textless_Samnee_Variant.jpg/revision/latest?cb=20241205040145"},{"name":"Zatanna","rarity":"epic","id":"zatanna","subtitle":"Hero","details":"Zatanna Zatara, stage magician and real sorceress, debuted in Hawkman #4 in 1964; she casts spells by speaking backwards.","image":"https://static.wikia.nocookie.net/marvel_dc/images/d/da/Zatanna_Prime_Earth_0019.jpeg/revision/latest/scale-to-width-down/1200?cb=20250219204554"},{"name":"Atom Eve","rarity":"epic","id":"atom-eve","subtitle":"Hero","details":"Samantha Eve Wilkins can rearrange matter at will, reshaping objects and energy; a teen hero and Invincible's closest ally in Image's series.","image":"https://static.wikia.nocookie.net/imagecomics/images/4/42/Invincible_%282005%29_023_page_23.jpg/revision/latest?cb=20070201200103"},{"name":"Bloodshot","rarity":"epic","id":"bloodshot","subtitle":"Anti-Hero","details":"Ray Garrison is rebuilt by blood-borne nanites that heal any wound and rewrite his memories — Valiant's super-soldier fighting to reclaim his past.","image":"https://upload.wikimedia.org/wikipedia/en/3/39/Bloodshot_1_2012.jpg"},{"name":"Michelangelo","rarity":"epic","id":"michelangelo","subtitle":"Hero","details":"The fun-loving youngest Turtle, a nunchaku-swinging party dude whose jokes hide real heart and surprising skill with any weapon he picks up.","image":"https://upload.wikimedia.org/wikipedia/en/f/f3/Michelangelo_%28Teenage_Mutant_Ninja_Turtles%29.jpg"},{"name":"Savage Dragon","rarity":"epic","id":"savage-dragon","subtitle":"Hero","details":"A super-strong, green-finned amnesiac who joins the Chicago police to battle freakish supervillains in Erik Larsen's long-running Image series.","image":"https://upload.wikimedia.org/wikipedia/en/9/9c/TheSavageDragonMini1.jpg"},{"name":"Shredder","rarity":"epic","id":"shredder","subtitle":"Villain","details":"Oroku Saki, the bladed-armor leader of the Foot Clan, whose blood feud with Splinter makes him the Turtles' most relentless enemy.","image":"https://upload.wikimedia.org/wikipedia/en/4/4a/Shredder_TMNT.webp"},{"name":"The Mask","rarity":"epic","id":"the-mask","subtitle":"Anti-Hero","details":"Whoever wears the ancient wooden mask gains reality-warping, cartoon-physics powers — and loses every inhibition, as mild Stanley Ipkiss learns.","image":"https://upload.wikimedia.org/wikipedia/en/8/8f/The_Mask-comic.jpg"},{"name":"Tommy Oliver (Green Ranger)","rarity":"epic","id":"tommy-oliver-green-ranger","subtitle":"Hero","details":"Introduced as Rita's evil Green Ranger, Tommy Oliver breaks her spell to become the Power Rangers' sixth member — and the team's defining Ranger.","image":"https://static.wikia.nocookie.net/powerrangers/images/a/a2/Green_Ranger_%28Tommy_Boom%21_comics%29_Profile.png/revision/latest?cb=20231016040348"},{"name":"Violator","rarity":"epic","id":"violator","subtitle":"Villain","details":"A demon of Hell who takes the form of a corpulent clown to torment Spawn and goad the hellspawn toward his destiny of leading Hell's army.","image":"https://static.wikia.nocookie.net/imagecomics/images/2/27/Violator_Vol_1_1.jpeg/revision/latest?cb=20150407213211"},{"name":"Ant-Man (Scott Lang)","rarity":"rare","id":"ant-man-scott-lang","subtitle":"Hero","details":"Scott Lang, a reformed thief and electronics expert, stole the Ant-Man suit to save his daughter Cassie and earned the right to keep wearing it.","image":"https://upload.wikimedia.org/wikipedia/en/3/38/Ant-Man_%28Scott_Lang%29.jpg"},{"name":"Apocalypse","rarity":"rare","id":"apocalypse","subtitle":"Villain","details":"En Sabah Nur, born in ancient Egypt millennia ago, is one of the first mutants, preaching that only the strong deserve to survive.","image":"https://upload.wikimedia.org/wikipedia/en/a/a0/Apocalypse_%28En_Sabah_Nur_-_circa_2009%29.jpg"},{"name":"Asgard","rarity":"rare","id":"asgard","subtitle":"Location","details":"The golden home of the Norse gods, a floating realm of warriors and wonders connected to Earth by the rainbow bridge called the Bifrost.","image":"https://static.wikia.nocookie.net/marveldatabase/images/2/29/Asgard_%28City%29_from_Thor_Vol_6_1_001.jpg/revision/latest"},{"name":"Carnage","rarity":"rare","id":"carnage","subtitle":"Villain","details":"Serial killer Cletus Kasady bonded with an offspring of the Venom symbiote, and the blood-red result was Carnage, chaos with a body count.","image":"https://upload.wikimedia.org/wikipedia/en/8/87/Carnage_%28Marvel_Comics_character%29.png"},{"name":"Cyclops","rarity":"rare","id":"cyclops","subtitle":"Hero","details":"Scott Summers debuted in X-Men #1 in 1963, the X-Men's field leader, firing uncontrollable optic blasts he contains with a ruby-quartz visor.","image":"https://upload.wikimedia.org/wikipedia/en/e/e9/Cyclops_%28Scott_Summers_circa_2019%29.png"},{"name":"Doctor Octopus","rarity":"rare","id":"doctor-octopus","subtitle":"Villain","details":"Otto Octavius debuted in The Amazing Spider-Man #3 in 1963, a brilliant scientist fused to four mechanical arms and consumed by his own genius.","image":"https://upload.wikimedia.org/wikipedia/en/b/bc/Dr._Octopus_Marvel.jpg"},{"name":"Fantastic Four","rarity":"rare","id":"fantastic-four","subtitle":"Team","details":"Marvel's First Family debuted in Fantastic Four #1 in 1961, four explorers transformed by cosmic rays into adventurers of the impossible.","image":"https://upload.wikimedia.org/wikipedia/en/1/1b/Fantastic_Four_%28Marvel_Comics_characters%29.jpg"},{"name":"Ghost Rider","rarity":"rare","id":"ghost-rider","subtitle":"Anti-Hero","details":"Stunt rider Johnny Blaze debuted in Marvel Spotlight #5 in 1972, cursed to become the Ghost Rider, a flaming-skulled Spirit of Vengeance.","image":"https://upload.wikimedia.org/wikipedia/en/6/6e/Ghost_Rider_first_issue_cover.png"},{"name":"Guardians of the Galaxy","rarity":"rare","id":"guardians-of-the-galaxy","subtitle":"Team","details":"A band of cosmic misfits, Star-Lord, Gamora, Drax, Rocket and Groot, who bicker like family while standing between the galaxy and annihilation.","image":"https://upload.wikimedia.org/wikipedia/en/8/8f/GuardiansoftheGalaxy.jpg"},{"name":"Hela","rarity":"rare","id":"hela","subtitle":"Villain","details":"The Asgardian Goddess of Death debuted in Journey into Mystery #102 in 1964, ruling the realm of Hel and forever coveting the souls of heroes.","image":"https://upload.wikimedia.org/wikipedia/en/d/db/Hela.png"},{"name":"Human Torch","rarity":"rare","id":"human-torch","subtitle":"Hero","details":"Johnny Storm debuted in Fantastic Four #1 in 1961, bursting into flame with a cry of 'Flame on!' as the team's hot-headed youngest member.","image":"https://upload.wikimedia.org/wikipedia/en/c/c7/Human_Torch_%28Johnny_Storm%29.png"},{"name":"Invisible Woman","rarity":"rare","id":"invisible-woman","subtitle":"Hero","details":"Sue Storm debuted in Fantastic Four #1 in 1961, turning invisible and projecting powerful force fields as the true backbone of the team.","image":"https://upload.wikimedia.org/wikipedia/en/e/e4/Invisible_Woman.png"},{"name":"Juggernaut","rarity":"rare","id":"juggernaut","subtitle":"Villain","details":"Cain Marko, Xavier's stepbrother, claimed the Crimson Gem of Cyttorak and became the Juggernaut, an unstoppable force nothing can slow.","image":"https://upload.wikimedia.org/wikipedia/en/4/44/Juggernaut2.PNG"},{"name":"Kang the Conqueror","rarity":"rare","id":"kang-the-conqueror","subtitle":"Villain","details":"A time-traveling warlord from the far future, Kang battles the Avengers across centuries, splintered into countless rival versions of himself.","image":"https://upload.wikimedia.org/wikipedia/en/0/06/Kang_the_Conqueror.png"},{"name":"Killmonger","rarity":"rare","id":"killmonger","subtitle":"Villain","details":"Erik Killmonger debuted in Jungle Action #6 in 1973, an exiled Wakandan warrior who returned again and again to challenge T'Challa for the throne.","image":"https://static.wikia.nocookie.net/marveldatabase/images/f/f0/Wakanda_Vol_1_3_Textless.jpg/revision/latest"},{"name":"Moon Knight","rarity":"rare","id":"moon-knight","subtitle":"Anti-Hero","details":"Marc Spector debuted in Werewolf by Night #32 in 1975, a mercenary resurrected by the moon god Khonshu to serve as his fist of vengeance.","image":"https://static.wikia.nocookie.net/marveldatabase/images/d/d2/Marc_Spector_%28Earth-616%29_from_Vengeance_of_the_Moon_Knight_Vol_2_8_Cappuccio_Variant_cover.jpg/revision/latest"},{"name":"Ms. Marvel","rarity":"rare","id":"ms-marvel","subtitle":"Hero","details":"Kamala Khan, a Jersey City super-fan of Carol Danvers, awoke with polymorph powers that let her embiggen her fists to heroic proportions.","image":"https://upload.wikimedia.org/wikipedia/en/d/db/Kamala_Khan.jpg"},{"name":"Mysterio","rarity":"rare","id":"mysterio","subtitle":"Villain","details":"Quentin Beck debuted in The Amazing Spider-Man #13 in 1964, a Hollywood effects wizard whose illusions and drones make him the master of deception.","image":"https://upload.wikimedia.org/wikipedia/en/4/45/Mysterio.png"},{"name":"She-Hulk","rarity":"rare","id":"she-hulk","subtitle":"Hero","details":"Jennifer Walters debuted in The Savage She-Hulk #1 in 1980, gaining Hulk power through a blood transfusion from her cousin Bruce Banner.","image":"https://static.wikia.nocookie.net/marveldatabase/images/e/e0/Sensational_She-Hulk_Vol_2_10_Andolfo_Variant_Textless.jpg/revision/latest"},{"name":"Spider-Man (Miles Morales)","rarity":"rare","id":"spider-man-miles-morales","subtitle":"Hero","details":"Brooklyn teen Miles Morales debuted in Ultimate Fallout #4 in 2011, gaining spider-powers plus camouflage and a bio-electric venom strike.","image":"https://upload.wikimedia.org/wikipedia/en/8/8e/Spider-Man_%28Miles_Morales%29_character_art.png"},{"name":"Vision","rarity":"rare","id":"vision","subtitle":"Hero","details":"The synthezoid Vision debuted in The Avengers #57 in 1968, built by Ultron to destroy the Avengers, then choosing instead to join them.","image":"https://upload.wikimedia.org/wikipedia/en/3/3d/Vision_%28Marvel_Comics%29.png"},{"name":"Wakanda","rarity":"rare","id":"wakanda","subtitle":"Location","details":"A hidden African nation never conquered by outsiders, built on a mound of vibranium and guarded for generations by the Black Panther.","image":"https://static.wikia.nocookie.net/marveldatabase/images/c/c5/Birnin_Zana_from_Black_Panther_World_of_Wakanda_Vol_1_1_Hip-Hop_Variant_cover_001.jpg/revision/latest"},{"name":"War Machine","rarity":"rare","id":"war-machine","subtitle":"Hero","details":"James 'Rhodey' Rhodes, Stark's longtime friend and a Marine pilot, straps into the heavily armed War Machine armor when diplomacy runs out.","image":"https://upload.wikimedia.org/wikipedia/en/e/e6/War_Machine_%28James_Rhodes%29.png"},{"name":"X-Men","rarity":"rare","id":"x-men","subtitle":"Team","details":"Debuting in X-Men #1 in 1963, Professor Xavier's mutant students fight for a world that fears and hates them, beginning with five teenagers.","image":"https://upload.wikimedia.org/wikipedia/en/d/db/X-Men_%28Vol._6%29_No._2_Mahmud_Asrar_Variant_%28Textless%29.jpg"},{"name":"Batgirl (Barbara Gordon)","rarity":"rare","id":"batgirl-barbara-gordon","subtitle":"Hero","details":"Barbara Gordon, Commissioner Gordon's daughter, debuted as Batgirl in 1967 and later guided other heroes as Oracle.","image":"https://static.wikia.nocookie.net/marvel_dc/images/8/80/Nightwing_Vol_4_85_Redondo_Variant_Textless_%28modified%29.jpg/revision/latest/scale-to-width-down/1200?cb=20261007163658"},{"name":"Black Canary","rarity":"rare","id":"black-canary","subtitle":"Hero","details":"Dinah Lance carries on a hero name dating to 1947; her ultrasonic Canary Cry and martial arts anchor the Justice League.","image":"https://static.wikia.nocookie.net/marvel_dc/images/9/93/Birds_of_Prey_Vol_5_13_Textless_Guidry_Variant.jpg/revision/latest?cb=20240905144111"},{"name":"Booster Gold","rarity":"rare","id":"booster-gold","subtitle":"Hero","details":"Michael Jon Carter, a disgraced 25th-century athlete, debuted in 1986 and time-traveled back to become a hero for fame.","image":"https://static.wikia.nocookie.net/marvel_dc/images/7/76/Justice_League_The_Omega_Act_Special_Vol_1_1_Textless_Aguillo_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20251004032019"},{"name":"Captain Cold","rarity":"rare","id":"captain-cold","subtitle":"Villain","details":"Leonard Snart, leader of the Rogues, debuted in 1957; his cold gun can reach absolute zero, freezing even the Flash.","image":"https://static.wikia.nocookie.net/marvel_dc/images/a/a6/The_Flash_Vol_5_37_Textless.jpg/revision/latest?cb=20180111155826"},{"name":"Doomsday","rarity":"rare","id":"doomsday","subtitle":"Villain","details":"Doomsday, a Kryptonian horror engineered to evolve past death, debuted in 1992 as the beast that killed Superman.","image":"https://static.wikia.nocookie.net/marvel_dc/images/a/a8/Batman_Superman_Vol_1_3.1_Doomsday_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20130925200353"},{"name":"General Zod","rarity":"rare","id":"general-zod","subtitle":"Villain","details":"Dru-Zod, a Kryptonian military leader, debuted in Adventure Comics #283 in 1961 and was exiled to the Phantom Zone.","image":"https://static.wikia.nocookie.net/marvel_dc/images/6/6f/Superman_Vol_6_42_Textless_Sampere_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20260926045558"},{"name":"Gorilla Grodd","rarity":"rare","id":"gorilla-grodd","subtitle":"Villain","details":"Gorilla Grodd, a hyper-intelligent ape of Gorilla City, debuted in The Flash #106 in 1959 with telepathic might.","image":"https://static.wikia.nocookie.net/marvel_dc/images/8/8b/Gorilla_Grodd_0002.jpg/revision/latest?cb=20191221130814"},{"name":"Gotham City","rarity":"rare","id":"gotham-city","subtitle":"Location","details":"Gotham City, Batman's home since 1940; a gothic maze of gargoyles, crime families and Arkham's worst inmates.","image":"https://static.wikia.nocookie.net/marvel_dc/images/f/fe/Gotham_City_0001.jpg/revision/latest/scale-to-width-down/1200?cb=20140430113726"},{"name":"Green Lantern (John Stewart)","rarity":"rare","id":"green-lantern-john-stewart","subtitle":"Hero","details":"John Stewart, an architect and ex-Marine, was chosen as Hal Jordan's backup Green Lantern in 1971 and became a mainstay.","image":"https://static.wikia.nocookie.net/marvel_dc/images/3/37/Green_Lantern_The_Lost_Army_Vol_1_3_Variant_B.jpg/revision/latest?cb=20150820004846"},{"name":"Hawkgirl","rarity":"rare","id":"hawkgirl","subtitle":"Hero","details":"Hawkgirl wields Nth metal wings and a mace; her incarnations since 1940 share a cycle of reincarnation with Hawkman.","image":"https://static.wikia.nocookie.net/marvel_dc/images/d/d7/Justice_League_Vol_4_3_Textless_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20180704070845"},{"name":"Hawkman","rarity":"rare","id":"hawkman","subtitle":"Hero","details":"Carter Hall debuted in Flash Comics #1 in 1940; a reincarnated warrior flying on Nth metal wings with ancient weapons.","image":"https://static.wikia.nocookie.net/marvel_dc/images/2/25/Hawkman_Vol_5_1_Textless.jpg/revision/latest?cb=20180613183242"},{"name":"Killer Croc","rarity":"rare","id":"killer-croc","subtitle":"Villain","details":"Waylon Jones debuted in 1983; a wrestler with a reptilian condition whose strength and rage grow ever more bestial.","image":"https://static.wikia.nocookie.net/marvel_dc/images/c/c8/Batman_and_Robin_Vol_2_23.4_Killer_Croc_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20130925195937"},{"name":"Lobo","rarity":"rare","id":"lobo","subtitle":"Anti-Hero","details":"Lobo, the last Czarnian, debuted in 1983; the self-proclaimed Main Man is a foul-mouthed, nearly unkillable bounty hunter.","image":"https://static.wikia.nocookie.net/marvel_dc/images/9/90/Justice_League_Vol_2_23.2_Lobo_Textless.jpg/revision/latest/scale-to-width-down/1200?cb=20130911185531"},{"name":"Metropolis","rarity":"rare","id":"metropolis","subtitle":"Location","details":"Metropolis, the City of Tomorrow and Superman's home; a gleaming skyline anchored by the Daily Planet globe.","image":"https://static.wikia.nocookie.net/marvel_dc/images/b/bb/Metropolis_001.jpg/revision/latest/scale-to-width-down/1200?cb=20170822195321"},{"name":"Mr. Freeze","rarity":"rare","id":"mr-freeze","subtitle":"Villain","details":"Victor Fries debuted in 1959; a cryogenics expert in a sub-zero suit, driven to save his terminally ill wife Nora.","image":"https://static.wikia.nocookie.net/marvel_dc/images/8/8f/Mister_Freeze_Prime_Earth_0001.jpg/revision/latest?cb=20130822212807"},{"name":"Peacemaker","rarity":"rare","id":"peacemaker","subtitle":"Anti-Hero","details":"Christopher Smith debuted in 1966; a ruthless vigilante who claims to love peace so much he will kill for it.","image":"https://static.wikia.nocookie.net/marvel_dc/images/6/62/Peacemaker_Tries_Hard%21_Vol_1_3_Joe_Quinones_Variant_Textless.jpg/revision/latest?cb=20231201155703"},{"name":"Ra's al Ghul","rarity":"rare","id":"ras-al-ghul","subtitle":"Villain","details":"Ra's al Ghul, the Demon's Head, debuted in Batman #232 in 1971; an immortal eco-warrior leading the League of Assassins.","image":"https://static.wikia.nocookie.net/marvel_dc/images/3/32/Batman_One_Bad_Day_Ra%27s_al_Ghul_Textless.png/revision/latest?cb=20230323212039"},{"name":"Red Hood","rarity":"rare","id":"red-hood","subtitle":"Anti-Hero","details":"Jason Todd, the second Robin, died at the Joker's hands in 1988 and returned from the dead as the lethal Red Hood.","image":"https://static.wikia.nocookie.net/marvel_dc/images/2/2b/Red_Hood_The_Hill_Vol_1_5_Textless_Variant.jpg/revision/latest?cb=20240615144945"},{"name":"Robin (Damian Wayne)","rarity":"rare","id":"robin-damian-wayne","subtitle":"Hero","details":"Damian Wayne, son of Batman and Talia al Ghul, debuted in 2006; a League-trained assassin raised to become Robin.","image":"https://static.wikia.nocookie.net/marvel_dc/images/1/1c/Batman_and_Robin_Vol_3_27_Textless_Chew_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20251113140155"},{"name":"Robin (Tim Drake)","rarity":"rare","id":"robin-tim-drake","subtitle":"Hero","details":"Tim Drake deduced Batman's identity as a boy, debuted in 1989, and became the third Robin through skill, not tragedy.","image":"https://static.wikia.nocookie.net/marvel_dc/images/a/a4/Dark_Crisis_Young_Justice_Vol_1_5_Textless_Variant.jpg/revision/latest?cb=20221019011406"},{"name":"Scarecrow","rarity":"rare","id":"scarecrow","subtitle":"Villain","details":"Jonathan Crane, a fear-obsessed psychologist, debuted in World's Finest #3 in 1941 and weaponizes fear toxin.","image":"https://static.wikia.nocookie.net/marvel_dc/images/f/fa/Scarecrow_Prime_Earth_0002.jpg/revision/latest/scale-to-width-down/1200?cb=20210307204046"},{"name":"Suicide Squad","rarity":"rare","id":"suicide-squad","subtitle":"Team","details":"Task Force X: imprisoned villains sent on black-ops missions for Amanda Waller, revived in Legends #3 in 1987.","image":"https://static.wikia.nocookie.net/marvel_dc/images/2/2c/Suicide_Squad_Dream_Team_Vol_1_1_Textless.jpg/revision/latest?cb=20240315150505"},{"name":"Teen Titans","rarity":"rare","id":"teen-titans","subtitle":"Team","details":"DC's young hero team, formed in The Brave and the Bold #54 in 1964 when sidekicks Robin, Kid Flash and Aqualad teamed up.","image":"https://static.wikia.nocookie.net/marvel_dc/images/e/e3/Teen_Titans_Vol_7_1_Textless_Variant.jpg/revision/latest/scale-to-width-down/1200?cb=20260902145139"},{"name":"The Flash (Wally West)","rarity":"rare","id":"the-flash-wally-west","subtitle":"Hero","details":"Wally West, Barry Allen's nephew, gained speed in a copycat lab accident in 1959, served as Kid Flash, then took the mantle.","image":"https://static.wikia.nocookie.net/marvel_dc/images/a/ae/The_Flash_Vol_6_14_Textless_Sampere_Variant.webp/revision/latest?cb=20241030172009"},{"name":"Abe Sapien","rarity":"rare","id":"abe-sapien","subtitle":"Hero","details":"An amphibious B.P.R.D. agent found in a water-filled tube beneath a hospital, Abe Sapien is Hellboy's gentle, bookish and deadly capable partner.","image":"https://static.wikia.nocookie.net/hellboy/images/0/08/HonE_Abecover.jpg/revision/latest?cb=20121017150954"},{"name":"Allen the Alien","rarity":"rare","id":"allen-the-alien","subtitle":"Hero","details":"A Unopan officer of the Coalition of Planets who tests Earth's champions, growing stronger after every defeat; a loyal ally of Invincible.","image":"https://static.wikia.nocookie.net/imagecomics/images/f/fa/Invincible_Vol_1_134.jpg/revision/latest?cb=20170201234910"},{"name":"Angela","rarity":"rare","id":"angela","subtitle":"Hero","details":"An elite angel and bounty hunter of Heaven, created to hunt hellspawn, who becomes one of Spawn's most formidable rivals and uneasy allies.","image":"https://static.wikia.nocookie.net/imagecomics/images/a/a5/Angela_hunter.jpg/revision/latest?cb=20070226213118"},{"name":"Battle Beast","rarity":"rare","id":"battle-beast","subtitle":"Anti-Hero","details":"A lion-like warrior who roams the galaxy seeking ever stronger opponents, caring for nothing but a worthy fight in Image's Invincible.","image":"https://static.wikia.nocookie.net/imagecomics/images/f/f9/Invincible_Vol_1_115_001.jpg/revision/latest?cb=20150630173620"},{"name":"Conquest","rarity":"rare","id":"conquest","subtitle":"Villain","details":"A sadistic veteran Viltrumite enforcer sent to finish Earth's conquest, infamous for his brutal showdown with Invincible, Atom Eve and Omni-Man.","image":"https://static.wikia.nocookie.net/imagecomics/images/7/7d/Invincible_TPB_%28New_Edition%29_Vol_11_Textless.jpg/revision/latest?cb=20260504204632"},{"name":"Donatello","rarity":"rare","id":"donatello","subtitle":"Hero","details":"The Turtles' resident genius, Donatello builds their vehicles and gadgets and fights with a bo staff; brains first, but never a pushover.","image":"https://upload.wikimedia.org/wikipedia/en/5/5a/Donatello_%28Teenage_Mutant_Ninja_Turtles%29.jpg"},{"name":"Hit-Girl","rarity":"rare","id":"hit-girl","subtitle":"Anti-Hero","details":"Mindy McCready was raised by her father Big Daddy to be a pint-sized killing machine, the breakout star of Mark Millar's Kick-Ass comics.","image":"https://upload.wikimedia.org/wikipedia/en/e/e3/Hit-Girl_in_Rome_cover.jpg"},{"name":"Raphael","rarity":"rare","id":"raphael","subtitle":"Hero","details":"The hot-headed Turtle with twin sai, Raphael's temper and sarcasm mask fierce loyalty — he's always first into a fight for his brothers.","image":"https://upload.wikimedia.org/wikipedia/en/7/72/Raphael_%28Teenage_Mutant_Ninja_Tutles%29.jpg"},{"name":"Rita Repulsa","rarity":"rare","id":"rita-repulsa","subtitle":"Villain","details":"An alien sorceress freed after 10,000 years in a space dumpster, Rita Repulsa wages war on Earth with monsters grown from clay in her palace.","image":"https://static.wikia.nocookie.net/powerrangers/images/9/93/Rita_Repulsa_BoomComics.jpg/revision/latest?cb=20160901022319"},{"name":"Samaritan","rarity":"rare","id":"samaritan","subtitle":"Hero","details":"Astro City's premier hero, Samaritan flies at incredible speed to answer every emergency, counting the seconds each rescue costs him.","image":"https://static.wikia.nocookie.net/astrocity/images/e/e2/Samaritan_0001.jpg/revision/latest?cb=20150629213953"},{"name":"Splinter","rarity":"rare","id":"splinter","subtitle":"Supporting","details":"Once Hamato Yoshi — or his pet rat, depending on the telling — the mutant sensei who raised and trained the four Turtles in ninjutsu.","image":"https://upload.wikimedia.org/wikipedia/en/0/00/Splinter_%28character%29.png"},{"name":"X-O Manowar","rarity":"rare","id":"x-o-manowar","subtitle":"Hero","details":"Aric of Dacia, a Visigoth warrior abducted by aliens, bonds with the sacred X-O armor and returns to modern Earth in Valiant's flagship series.","image":"https://upload.wikimedia.org/wikipedia/en/f/f8/X-O_Manowar_1_Pullbox.jpg"},{"name":"Abomination","rarity":"uncommon","id":"abomination","subtitle":"Villain","details":"Emil Blonsky debuted in Tales to Astonish #90 in 1967, a spy transformed by gamma radiation into the Abomination, the Hulk's monstrous rival.","image":"https://static.wikia.nocookie.net/marveldatabase/images/7/77/Incredible_Hulk_Vol_6_30_Hotz_Second_Printing_Variant.jpg/revision/latest?cb=20260215055934"},{"name":"Aunt May","rarity":"uncommon","id":"aunt-may","subtitle":"Supporting","details":"May Parker debuted alongside her nephew in Amazing Fantasy #15 in 1962, the frail, iron-willed aunt whose love keeps Peter Parker grounded.","image":"https://upload.wikimedia.org/wikipedia/en/5/50/Aunt_May_Marvel_Comics.png"},{"name":"Avengers Tower","rarity":"uncommon","id":"avengers-tower","subtitle":"Location","details":"The Manhattan skyscraper formerly known as Stark Tower serves as the Avengers' headquarters, laboratory and very public symbol in New York.","image":"https://static.wikia.nocookie.net/marveldatabase/images/a/ae/Avengers_Tower_from_New_Avengers_Vol_1_10_001.png/revision/latest?cb=20160708052447"},{"name":"Baron Zemo","rarity":"uncommon","id":"baron-zemo","subtitle":"Villain","details":"A masked mastermind sworn to destroy Captain America and the Avengers, Zemo leads the Masters of Evil in a vendetta carried across generations.","image":"https://upload.wikimedia.org/wikipedia/en/4/4c/Baron-zemo.jpg"},{"name":"Beast","rarity":"uncommon","id":"beast","subtitle":"Hero","details":"Hank McCoy debuted in X-Men #1 in 1963, a brilliant biochemist whose simian strength and, later, blue fur never dimmed his love of learning.","image":"https://upload.wikimedia.org/wikipedia/en/0/0b/Beast_%28Hank_McCoy_-_circa_2019%29.png"},{"name":"Bullseye","rarity":"uncommon","id":"bullseye","subtitle":"Villain","details":"The assassin called Bullseye debuted in Daredevil #131 in 1976 and can turn any object, from a paper clip to a toothpick, into a lethal weapon.","image":"https://upload.wikimedia.org/wikipedia/en/c/c7/Bullseye_%28Marvel_Comics_character%29.png"},{"name":"Cable","rarity":"uncommon","id":"cable","subtitle":"Anti-Hero","details":"Nathan Summers, son of Cyclops, was raised in a war-torn future and returned as Cable, a time-traveling soldier with a techno-organic arm.","image":"https://upload.wikimedia.org/wikipedia/en/b/ba/Cable_%28Nathan_Summers%29.png"},{"name":"Colossus","rarity":"uncommon","id":"colossus","subtitle":"Hero","details":"Piotr Rasputin debuted in Giant-Size X-Men #1 in 1975, a Russian farm boy and painter who transforms his body into living steel.","image":"https://upload.wikimedia.org/wikipedia/en/2/26/Colossus-AvX_Consequences.jpg"},{"name":"Defenders","rarity":"uncommon","id":"defenders","subtitle":"Team","details":"Marvel's famous 'non-team' debuted in Marvel Feature #1 in 1971, Doctor Strange, the Hulk and Namor joining forces only when the world demanded it.","image":"https://upload.wikimedia.org/wikipedia/en/a/a6/Defenders_%28Marvel_Comics_team%29.jpg"},{"name":"Dormammu","rarity":"uncommon","id":"dormammu","subtitle":"Villain","details":"Ruler of the Dark Dimension, Dormammu debuted in Strange Tales #126 in 1964, a being of pure mystic energy forever scheming to absorb Earth.","image":"https://upload.wikimedia.org/wikipedia/en/8/80/Dormammu.png"},{"name":"Drax","rarity":"uncommon","id":"drax","subtitle":"Hero","details":"Drax the Destroyer is a hulking warrior forged for one purpose: vengeance on Thanos, the titan who destroyed his family.","image":"https://upload.wikimedia.org/wikipedia/en/0/02/Drax-cover.jpg"},{"name":"Electro","rarity":"uncommon","id":"electro","subtitle":"Villain","details":"Max Dillon debuted in The Amazing Spider-Man #9 in 1964, a lineman struck by lightning who became a living generator of electrical power.","image":"https://upload.wikimedia.org/wikipedia/en/4/41/Electro_-_Alex_Ross.jpg"},{"name":"Elektra","rarity":"uncommon","id":"elektra","subtitle":"Anti-Hero","details":"Elektra Natchios debuted in Daredevil #168 in 1981, Frank Miller's sai-wielding assassin whose love and lethality both target Matt Murdock.","image":"https://upload.wikimedia.org/wikipedia/en/a/af/Elektra_3.jpg"},{"name":"Falcon","rarity":"uncommon","id":"falcon","subtitle":"Hero","details":"Sam Wilson debuted in Captain America #117 in 1969, Captain America's flying partner, soaring on mechanical wings beside his falcon Redwing.","image":"https://upload.wikimedia.org/wikipedia/en/9/9e/Falcon_%28Samuel_Thomas_%22Sam%22_Wilson%29.png"},{"name":"Gambit","rarity":"uncommon","id":"gambit","subtitle":"Hero","details":"Remy LeBeau debuted in Uncanny X-Men #266 in 1990, a Cajun thief who charges playing cards with kinetic energy and throws them like grenades.","image":"https://static.wikia.nocookie.net/marveldatabase/images/4/46/Uncanny_X-Men_Vol_6_12_Clarke_Variant_Textless.jpg/revision/latest?cb=20250314183728"},{"name":"Gamora","rarity":"uncommon","id":"gamora","subtitle":"Hero","details":"Raised and weaponized by Thanos after her people were destroyed, Gamora broke free to become the deadliest woman in the galaxy and a Guardian.","image":"https://upload.wikimedia.org/wikipedia/en/0/08/Gamora-cover.jpg"},{"name":"Groot","rarity":"uncommon","id":"groot","subtitle":"Hero","details":"A Flora Colossus from Planet X, Groot can regrow from a twig and say only 'I am Groot,' yet his friends understand every word.","image":"https://static.wikia.nocookie.net/marveldatabase/images/6/60/Groot_%28Earth-616%29_from_Infinity_Countdown_Vol_1_1_001.jpg/revision/latest?cb=20180308012708"},{"name":"Iceman","rarity":"uncommon","id":"iceman","subtitle":"Hero","details":"Bobby Drake debuted in X-Men #1 in 1963, the X-Men's wisecracking youngest founder, able to freeze moisture into ice forms at will.","image":"https://upload.wikimedia.org/wikipedia/en/0/03/Iceman.png"},{"name":"J. Jonah Jameson","rarity":"uncommon","id":"j-jonah-jameson","subtitle":"Supporting","details":"The Daily Bugle's blustering publisher debuted in The Amazing Spider-Man #1 in 1963, waging endless editorial war on the 'menace' Spider-Man.","image":"https://upload.wikimedia.org/wikipedia/en/9/9d/J._Jonah_Jameson.png"},{"name":"Jessica Jones","rarity":"uncommon","id":"jessica-jones","subtitle":"Hero","details":"A retired hero turned hard-drinking private investigator, Jessica Jones debuted in Alias #1 in 2001 with super strength and a detective's instincts.","image":"https://static.wikia.nocookie.net/marveldatabase/images/e/ec/Jessica_Jones_Vol_2_4_Textless.jpg/revision/latest?cb=20161018161503"},{"name":"Kraven the Hunter","rarity":"uncommon","id":"kraven-the-hunter","subtitle":"Villain","details":"Sergei Kravinoff debuted in The Amazing Spider-Man #15 in 1964, a big-game hunter who set his sights on the most dangerous prey of all: Spider-Man.","image":"https://upload.wikimedia.org/wikipedia/en/2/21/Kraven_the_Hunter_%282017_Design%29.webp"},{"name":"Lizard","rarity":"uncommon","id":"lizard","subtitle":"Villain","details":"Dr. Curt Connors debuted in The Amazing Spider-Man #6 in 1963, a one-armed scientist whose reptile serum regrew his arm and unleashed the Lizard.","image":"https://upload.wikimedia.org/wikipedia/en/9/91/Lizard_%28Curt_Connors%29.jpg"},{"name":"Luke Cage","rarity":"uncommon","id":"luke-cage","subtitle":"Hero","details":"Framed and imprisoned, Carl Lucas gained unbreakable skin in a sabotaged experiment and debuted in Hero for Hire #1 in 1972 as Luke Cage, Power Man.","image":"https://upload.wikimedia.org/wikipedia/en/f/f9/Luke_Cage_by_Stuart_Immonen.png"},{"name":"MODOK","rarity":"uncommon","id":"modok","subtitle":"Villain","details":"Former A.I.M. technician George Tarleton was mutated into MODOK, a giant-headed Mental Organism Designed Only for Killing, in 1967.","image":"https://upload.wikimedia.org/wikipedia/en/b/ba/M.O.D.O.K_%28Marvel_Comics_character%29.png"},{"name":"Mandarin","rarity":"uncommon","id":"mandarin","subtitle":"Villain","details":"The Mandarin debuted in Tales of Suspense #50 in 1964, a would-be world conqueror wielding ten alien power rings of Makluan origin.","image":"https://upload.wikimedia.org/wikipedia/en/c/ca/Mandarin_%28Marvel_Comics_character_circa_2011%29.png"},{"name":"Mary Jane Watson","rarity":"uncommon","id":"mary-jane-watson","subtitle":"Supporting","details":"Mary Jane Watson made her famous entrance in The Amazing Spider-Man #42 in 1966: 'Face it, Tiger... you just hit the jackpot!'","image":"https://upload.wikimedia.org/wikipedia/en/6/68/Mary_Jane_Watson_%28circa_2007%29.png"},{"name":"Mephisto","rarity":"uncommon","id":"mephisto","subtitle":"Villain","details":"Marvel's devil figure debuted in Silver Surfer #3 in 1968, a demon who bargains for the souls of heroes in contracts that always hide a twist.","image":"https://upload.wikimedia.org/wikipedia/en/3/3e/Mephisto_%28Marvel_Comics_character%29.png"},{"name":"Nebula","rarity":"uncommon","id":"nebula","subtitle":"Anti-Hero","details":"A cybernetically enhanced space pirate and relentless rival to Gamora, Nebula was forged in Thanos's shadow and answers to no one.","image":"https://upload.wikimedia.org/wikipedia/en/a/a9/Nebula_%28Marvel_Comics_character_-_circa_2020%29.jpg"},{"name":"Nick Fury","rarity":"uncommon","id":"nick-fury","subtitle":"Supporting","details":"Nick Fury debuted in Sgt. Fury #1 in 1963, a World War II sergeant who became the one-eyed spymaster directing S.H.I.E.L.D. from the shadows.","image":"https://upload.wikimedia.org/wikipedia/en/7/71/Nick_Fury_I.png"},{"name":"Nightcrawler","rarity":"uncommon","id":"nightcrawler","subtitle":"Hero","details":"Kurt Wagner debuted in Giant-Size X-Men #1 in 1975, a gentle, swashbuckling German mutant who teleports in a puff of brimstone smoke.","image":"https://static.wikia.nocookie.net/marveldatabase/images/3/31/Uncanny_X-Men_Vol_6_3_Textless.jpg/revision/latest?cb=20240703181805"},{"name":"Pepper Potts","rarity":"uncommon","id":"pepper-potts","subtitle":"Supporting","details":"Pepper Potts debuted in Tales of Suspense #45 in 1963, Tony Stark's indispensable assistant who eventually ran his company and armored up as Rescue.","image":"https://upload.wikimedia.org/wikipedia/en/2/25/Virginia_%27Pepper%27_Potts.png"},{"name":"Rhino","rarity":"uncommon","id":"rhino","subtitle":"Villain","details":"Aleksei Sytsevich debuted in The Amazing Spider-Man #41 in 1966, a Russian thug bonded into a rhino-like suit of immense, charging strength.","image":"https://upload.wikimedia.org/wikipedia/en/f/fc/Rhinopreview.jpg"},{"name":"Rocket Raccoon","rarity":"uncommon","id":"rocket-raccoon","subtitle":"Hero","details":"A genetically engineered raccoon-like creature and master of weapons and tactics, Rocket treats every firefight as a chance to steal spare parts.","image":"https://upload.wikimedia.org/wikipedia/en/1/1b/Rocketraccoon.png"},{"name":"Rogue","rarity":"uncommon","id":"rogue","subtitle":"Hero","details":"Rogue debuted in Avengers Annual #10 in 1981, a Southern mutant whose touch steals powers and memories, leaving her unable to safely touch anyone.","image":"https://upload.wikimedia.org/wikipedia/en/9/95/Rogue_%28Marvel_Comics%29.png"},{"name":"Sabretooth","rarity":"uncommon","id":"sabretooth","subtitle":"Villain","details":"Victor Creed debuted in Iron Fist #14 in 1977, a savage mutant with claws and a healing factor who shares a blood-soaked history with Wolverine.","image":"https://upload.wikimedia.org/wikipedia/en/c/c7/Sabretooth_%28Victor_Creed%29.png"},{"name":"Star-Lord","rarity":"uncommon","id":"star-lord","subtitle":"Hero","details":"Peter Quill, a half-human space outlaw raised by Ravager pirates, leads the Guardians of the Galaxy with a blaster, a jetpack and a vintage mixtape.","image":"https://upload.wikimedia.org/wikipedia/en/1/15/ST1.PNG"},{"name":"Taskmaster","rarity":"uncommon","id":"taskmaster","subtitle":"Villain","details":"Taskmaster debuted in The Avengers #195 in 1980, a mercenary who copies any fighting style he sees thanks to his photographic reflexes.","image":"https://static.wikia.nocookie.net/marveldatabase/images/c/c5/Anthony_Masters_%28Earth-616%29_from_Daredevil_Vol_8_23_001.jpg/revision/latest?cb=20260805185041"},{"name":"Thing","rarity":"uncommon","id":"thing","subtitle":"Hero","details":"Ben Grimm debuted in Fantastic Four #1 in 1961, a pilot turned rock-skinned strongman with a Brooklyn heart and one cry: 'It's clobberin' time!'","image":"https://upload.wikimedia.org/wikipedia/en/9/95/Thing_%28Marvel_Comics%29.png"},{"name":"Thunderbolts","rarity":"uncommon","id":"thunderbolts","subtitle":"Team","details":"The Thunderbolts shocked readers in 1997: presented as new heroes filling the Avengers' absence, they were secretly villains in disguise.","image":"https://upload.wikimedia.org/wikipedia/en/f/f0/Thunderbolts_%28Marvel_Comics_characters%29.png"},{"name":"Vulture","rarity":"uncommon","id":"vulture","subtitle":"Villain","details":"Adrian Toomes debuted in The Amazing Spider-Man #2 in 1963, an aging inventor whose flight harness lets him swoop down on Spider-Man's city.","image":"https://upload.wikimedia.org/wikipedia/en/4/46/Vulture_%28Adrian_Toomes%29.png"},{"name":"Wasp","rarity":"uncommon","id":"wasp","subtitle":"Hero","details":"Janet van Dyne debuted in Tales to Astonish #44 in 1963, a founding Avenger who shrinks to wasp size and even gave the team its name.","image":"https://upload.wikimedia.org/wikipedia/en/c/c0/AVEN071.jpg"},{"name":"Xavier's School","rarity":"uncommon","id":"xaviers-school","subtitle":"Location","details":"Xavier's School for Gifted Youngsters, a mansion in Westchester, New York, is both a refuge for young mutants and the X-Men's secret headquarters.","image":"https://static.wikia.nocookie.net/marveldatabase/images/7/76/Xavier%27s_School_for_Gifted_Youngsters_from_Free_Comic_Book_Day_2024_Blood_Hunt_X-Men_Vol_1_1_001.png/revision/latest?cb=20240508145533"},{"name":"Yondu","rarity":"uncommon","id":"yondu","subtitle":"Anti-Hero","details":"Yondu Udonta leads the Ravagers, a clan of space pirates, and aims his fin-controlled yaka arrow with nothing more than a piercing whistle.","image":"https://upload.wikimedia.org/wikipedia/en/c/c3/Yondu2cover.png"},{"name":"Young Avengers","rarity":"uncommon","id":"young-avengers","subtitle":"Team","details":"Teen heroes inspired by the Avengers debuted in Young Avengers #1 in 2005, carrying legacy names like Hawkeye, Hulkling and Wiccan into battle.","image":"https://upload.wikimedia.org/wikipedia/en/6/65/FullYNGAVNSP001000_400_col.jpg"},{"name":"Amanda Waller","rarity":"uncommon","id":"amanda-waller","subtitle":"Villain","details":"Amanda Waller, known as 'the Wall,' debuted in Legends #1 in 1986; the ruthless official who built the Suicide Squad.","image":"https://upload.wikimedia.org/wikipedia/en/8/8e/Amanda_Waller_Suicide_Squad_v5_8.png"},{"name":"Ares","rarity":"uncommon","id":"ares","subtitle":"Villain","details":"Ares, Greek god of war and Wonder Woman's ancient foe, debuted in Wonder Woman #1 in 1942, feeding on conflict.","image":"https://upload.wikimedia.org/wikipedia/en/5/56/Ares_God_of_War_DC_Comics_1987.png"},{"name":"Atlantis","rarity":"uncommon","id":"atlantis","subtitle":"Location","details":"Atlantis, the sunken undersea kingdom ruled by Aquaman, a realm of high science and older magic beneath the oceans.","image":"https://static.wikia.nocookie.net/marvel_dc/images/c/cd/Atlantis_07.jpg/revision/latest?cb=20090927214228"},{"name":"Atrocitus","rarity":"uncommon","id":"atrocitus","subtitle":"Villain","details":"Atrocitus, a survivor of the Manhunters' sector massacre, founded the Red Lantern Corps on rage and blood prophecy.","image":"https://upload.wikimedia.org/wikipedia/en/4/45/Atrocitus_%28art_work%29.png"},{"name":"Batcave","rarity":"uncommon","id":"batcave","subtitle":"Location","details":"The Batcave, Batman's headquarters beneath Wayne Manor; trophy-filled caverns housing the Batcomputer and the Batmobile.","image":"https://upload.wikimedia.org/wikipedia/en/3/37/Batcave-Batman1.png"},{"name":"Batwoman (Kate Kane)","rarity":"uncommon","id":"batwoman-kate-kane","subtitle":"Hero","details":"Kate Kane, Bruce Wayne's cousin, debuted as Batwoman in 2006; a West Point cadet turned Gotham vigilante.","image":"https://upload.wikimedia.org/wikipedia/en/9/93/Batwoman_01.jpg"},{"name":"Birds of Prey","rarity":"uncommon","id":"birds-of-prey","subtitle":"Team","details":"Birds of Prey, an all-women strike team guided by Oracle, debuted in 1996 around Black Canary and Barbara Gordon.","image":"https://upload.wikimedia.org/wikipedia/en/8/82/Birds_of_Prey_8_%28Jan_2010%29.png"},{"name":"Bizarro","rarity":"uncommon","id":"bizarro","subtitle":"Villain","details":"Bizarro, Superman's imperfect duplicate, debuted in Superboy #68 in 1958; his backwards logic makes him a tragic foe.","image":"https://upload.wikimedia.org/wikipedia/en/f/f2/Bizarro.png"},{"name":"Black Lightning","rarity":"uncommon","id":"black-lightning","subtitle":"Hero","details":"Jefferson Pierce, an Olympic athlete and teacher, debuted in 1977 as one of DC's first Black heroes with his own series.","image":"https://upload.wikimedia.org/wikipedia/en/c/c2/Black_Lightning_%28DC_Rebirth_version%29.png"},{"name":"Black Manta","rarity":"uncommon","id":"black-manta","subtitle":"Villain","details":"Black Manta, Aquaman's most relentless foe, debuted in Aquaman #35 in 1967, hunting vengeance in a ray-firing helmet.","image":"https://upload.wikimedia.org/wikipedia/en/5/5f/Black_Manta_Aquaman.webp"},{"name":"Blue Beetle (Jaime Reyes)","rarity":"uncommon","id":"blue-beetle-jaime-reyes","subtitle":"Hero","details":"Jaime Reyes, an El Paso teenager, debuted in 2006 when an alien scarab bonded to his spine as living armor.","image":"https://upload.wikimedia.org/wikipedia/en/8/8f/Blue_Beetle_Reyes.PNG"},{"name":"Clayface","rarity":"uncommon","id":"clayface","subtitle":"Villain","details":"Clayface, a name worn by shape-shifting mud monsters since 1940; the tragic actor Basil Karlo was the first.","image":"https://static.wikia.nocookie.net/marvel_dc/images/b/b6/Batgirl_Stephanie_Brown_0013.jpg/revision/latest?cb=20111018015424"},{"name":"Deadman","rarity":"uncommon","id":"deadman","subtitle":"Hero","details":"Boston Brand, a murdered circus aerialist, debuted in 1967; a ghost who possesses the living to seek justice.","image":"https://upload.wikimedia.org/wikipedia/en/7/70/Deadman_%28DC_Comics_Character%29.png"},{"name":"Doctor Fate","rarity":"uncommon","id":"doctor-fate","subtitle":"Hero","details":"Doctor Fate, agent of the Lords of Order since More Fun Comics #55 in 1940, wears the helmet of the god Nabu.","image":"https://upload.wikimedia.org/wikipedia/en/f/f1/Doctor_Fate_%28Kent_Nelson%29.png"},{"name":"Firefly","rarity":"uncommon","id":"firefly","subtitle":"Villain","details":"Garfield Lynns, a pyrotechnic arsonist, debuted in Detective Comics #184 in 1952 with a winged suit and flamethrowers.","image":"https://upload.wikimedia.org/wikipedia/en/0/0b/Firefly_%28Garfield_Lynns%29.png"},{"name":"Green Lantern (Guy Gardner)","rarity":"uncommon","id":"green-lantern-guy-gardner","subtitle":"Hero","details":"Guy Gardner, one of Earth's earliest Green Lantern picks, debuted in 1968; brash, stubborn and fiercely loyal.","image":"https://upload.wikimedia.org/wikipedia/en/7/74/Green_Lantern_%28Guy_Gardner%29.png"},{"name":"Green Lantern (Kyle Rayner)","rarity":"uncommon","id":"green-lantern-kyle-rayner","subtitle":"Hero","details":"Kyle Rayner, a comic book artist, became the last Green Lantern in 1994 when the Corps fell, bearing its sole ring.","image":"https://upload.wikimedia.org/wikipedia/en/d/d8/Green_Lantern_%28Kyle_Rayner%29.png"},{"name":"Green Lantern Corps","rarity":"uncommon","id":"green-lantern-corps","subtitle":"Team","details":"The Green Lantern Corps, intergalactic police chosen by the Guardians of Oa, patrol 3,600 sectors with will-powered rings.","image":"https://static.wikia.nocookie.net/marvel_dc/images/c/ce/Green_Lantern_Corps_Vol_4_9_Textless_Variant.jpg/revision/latest?cb=20251008124253"},{"name":"Hugo Strange","rarity":"uncommon","id":"hugo-strange","subtitle":"Villain","details":"Hugo Strange, one of Batman's oldest foes, debuted in Detective Comics #36 in 1940; a psychiatrist obsessed with him.","image":"https://upload.wikimedia.org/wikipedia/en/5/52/ModernHugoStrange.jpg"},{"name":"Huntress","rarity":"uncommon","id":"huntress","subtitle":"Anti-Hero","details":"Helena Bertinelli, a mafia-born vigilante, debuted as Huntress in 1989 and hunts Gotham's mob with a crossbow.","image":"https://upload.wikimedia.org/wikipedia/en/e/e8/Helena_Bertinelli_Huntress_%28Modern%29.png"},{"name":"Hush","rarity":"uncommon","id":"hush","subtitle":"Villain","details":"Thomas Elliot, Bruce Wayne's childhood friend, debuted in Batman #608 in 2002 as the bandaged manipulator Hush.","image":"https://upload.wikimedia.org/wikipedia/en/9/90/Hush_%28Thomas_%27Tommy%27_Elliot%29.png"},{"name":"Justice Society of America","rarity":"uncommon","id":"justice-society-of-america","subtitle":"Team","details":"The Justice Society of America, comics' first super-team, formed in All-Star Comics #3 in 1940 with the Golden Age greats.","image":"https://upload.wikimedia.org/wikipedia/en/5/5b/Justice_Society_of_America-vol3-1.jpg"},{"name":"Kid Flash (Bart Allen)","rarity":"uncommon","id":"kid-flash-bart-allen","subtitle":"Hero","details":"Bart Allen, Barry Allen's grandson from the future, debuted in 1994 as the hyperactive Impulse before taking the Kid Flash name.","image":"https://static.wikia.nocookie.net/marvel_dc/images/f/f4/Kid_Flash_Bart_Allen_0012.jpg/revision/latest?cb=20101014175832"},{"name":"Legion of Doom","rarity":"uncommon","id":"legion-of-doom","subtitle":"Team","details":"The Legion of Doom, a villain alliance formed for Challenge of the Superfriends in 1978, is based in a swamp Hall of Doom.","image":"https://static.wikia.nocookie.net/marvel_dc/images/4/42/Justice_League_Vol_4_35_Textless.jpg/revision/latest?cb=20211101060912"},{"name":"Livewire (Leslie Willis)","rarity":"uncommon","id":"livewire-leslie-willis","subtitle":"Villain","details":"Leslie Willis, a Metropolis shock jock electrocuted into a living lightning bolt, debuted in Superman: The Animated Series in 1997.","image":"https://upload.wikimedia.org/wikipedia/en/1/16/ActionComicsCv835.jpg"},{"name":"Mad Hatter","rarity":"uncommon","id":"mad-hatter","subtitle":"Villain","details":"Jervis Tetch, the Mad Hatter, debuted in Batman #49 in 1948, using mind-control technology hidden in hats.","image":"https://upload.wikimedia.org/wikipedia/en/0/0e/Mad_Hatter_%28Jervis_Tetch%29.png"},{"name":"Man-Bat","rarity":"uncommon","id":"man-bat","subtitle":"Villain","details":"Kirk Langstrom, a zoologist who tested a bat-gland serum on himself, debuted in Detective Comics #400 in 1970.","image":"https://upload.wikimedia.org/wikipedia/en/6/6c/Man-Bat.jpg"},{"name":"Metallo","rarity":"uncommon","id":"metallo","subtitle":"Villain","details":"John Corben debuted in Action Comics #252 in 1959; a cyborg with a Kryptonite heart, built to kill the Man of Steel.","image":"https://upload.wikimedia.org/wikipedia/en/2/26/Metallo_%28John_Corben%29.png"},{"name":"Miss Martian","rarity":"uncommon","id":"miss-martian","subtitle":"Hero","details":"M'gann M'orzz, a White Martian posing as Martian Manhunter's niece, debuted in 2006 with telepathy and shapeshifting.","image":"https://upload.wikimedia.org/wikipedia/en/2/2d/Miss_Martian.jpg"},{"name":"Ocean Master","rarity":"uncommon","id":"ocean-master","subtitle":"Villain","details":"Orm Marius, Aquaman's half-brother, debuted in Aquaman #29 in 1966 and schemes to seize the throne of Atlantis.","image":"https://upload.wikimedia.org/wikipedia/en/3/33/Ocean_Master_Aquaman_Vol_7_14.png"},{"name":"Parasite","rarity":"uncommon","id":"parasite","subtitle":"Villain","details":"The Parasite debuted in Action Comics #340 in 1966; he drains the powers and life force of anyone he touches.","image":"https://upload.wikimedia.org/wikipedia/en/0/0a/Parasitesuperman.PNG"},{"name":"Plastic Man","rarity":"uncommon","id":"plastic-man","subtitle":"Hero","details":"Patrick 'Eel' O'Brian, a crook doused in mysterious chemicals, debuted in 1941 and reformed as the stretchy Plastic Man.","image":"https://upload.wikimedia.org/wikipedia/commons/3/38/PoliceComicNo15.jpg"},{"name":"Reverse-Flash (Eobard Thawne)","rarity":"uncommon","id":"reverse-flash-eobard-thawne","subtitle":"Villain","details":"Eobard Thawne, a 25th-century Flash fan turned obsessive foe, debuted in The Flash #139 in 1963.","image":"https://upload.wikimedia.org/wikipedia/en/8/8e/Reverse-Flash_%28Eobard_Thawne%29.png"},{"name":"Solomon Grundy","rarity":"uncommon","id":"solomon-grundy","subtitle":"Villain","details":"Solomon Grundy, an undead swamp brute named for the nursery rhyme, debuted in All-American Comics #61 in 1944.","image":"https://upload.wikimedia.org/wikipedia/en/9/93/Solomon_Grundy_%28character%29.jpg"},{"name":"Stargirl","rarity":"uncommon","id":"stargirl","subtitle":"Hero","details":"Courtney Whitmore debuted in 1999; stepdaughter of a Golden Age sidekick, she wields the cosmic staff of Starman.","image":"https://upload.wikimedia.org/wikipedia/en/7/72/Stargirl_%28Courtney_Elizabeth_Whitmore%29.png"},{"name":"Superboy (Conner Kent)","rarity":"uncommon","id":"superboy-conner-kent","subtitle":"Hero","details":"Conner Kent, a clone grown from the DNA of Superman and Lex Luthor, debuted in 1993 in the wake of Superman's death.","image":"https://upload.wikimedia.org/wikipedia/en/8/83/Conner_Kent.png"},{"name":"Swamp Thing","rarity":"uncommon","id":"swamp-thing","subtitle":"Anti-Hero","details":"Swamp Thing, guardian of the Green, debuted in 1971; Alec Holland's memories live on within a plant elemental.","image":"https://static.wikia.nocookie.net/marvel_dc/images/0/0b/Swamp_Thing_Vol_5_25_Textless.jpg/revision/latest?cb=20131106222450"},{"name":"The Atom (Ray Palmer)","rarity":"uncommon","id":"the-atom-ray-palmer","subtitle":"Hero","details":"Ray Palmer debuted in Showcase #34 in 1961; a physicist who shrinks to subatomic size using a white-dwarf-star lens.","image":"https://upload.wikimedia.org/wikipedia/en/7/72/Atom_%28Ray_Palmer%29.png"},{"name":"The Question","rarity":"uncommon","id":"the-question","subtitle":"Anti-Hero","details":"Vic Sage, a faceless vigilante of Hub City, was created by Steve Ditko in 1967 and asks the questions others fear.","image":"https://upload.wikimedia.org/wikipedia/en/4/47/Question_%28Vic_Sage%29.jpg"},{"name":"The Spectre","rarity":"uncommon","id":"the-spectre","subtitle":"Anti-Hero","details":"The Spectre, God's Spirit of Vengeance, debuted in More Fun Comics #52 in 1940 and binds himself to human hosts.","image":"https://upload.wikimedia.org/wikipedia/en/d/de/The_Spectre_%28DC_Comics%29.png"},{"name":"Themyscira","rarity":"uncommon","id":"themyscira","subtitle":"Location","details":"Themyscira, the hidden island home of the Amazons and birthplace of Wonder Woman, a warrior society cut off from man's world.","image":"https://upload.wikimedia.org/wikipedia/en/6/66/Themyscira-floating.jpg"},{"name":"Trigon","rarity":"uncommon","id":"trigon","subtitle":"Villain","details":"Trigon, an interdimensional demon and Raven's father; a conqueror of worlds who uses his daughter as a portal to Earth.","image":"https://upload.wikimedia.org/wikipedia/en/2/26/Trigon_%28The_New_52_version%29.jpg"},{"name":"Vandal Savage","rarity":"uncommon","id":"vandal-savage","subtitle":"Villain","details":"Vandal Savage, an immortal caveman empowered by a strange meteorite, debuted in Green Lantern #10 in 1943.","image":"https://upload.wikimedia.org/wikipedia/en/b/b6/Vandal_Savage.png"},{"name":"Vixen","rarity":"uncommon","id":"vixen","subtitle":"Hero","details":"Mari McCabe debuted in Action Comics #521 in 1981; her Tantu Totem channels the abilities of any animal she chooses.","image":"https://upload.wikimedia.org/wikipedia/en/f/f3/Vixen_%28DC_Comics_character%29.png"},{"name":"Angstrom Levy","rarity":"uncommon","id":"angstrom-levy","subtitle":"Villain","details":"A dimension-hopping villain whose portal accident fuses the memories of countless alternate selves, driving his vendetta against Invincible.","image":"https://static.wikia.nocookie.net/imagecomics/images/6/69/Angstrom.PNG/revision/latest?cb=20130828072750"},{"name":"April O'Neil","rarity":"uncommon","id":"april-oneil","subtitle":"Supporting","details":"A reporter and scientist who befriends the Turtles, April O'Neil is their closest human friend and a bridge to the surface world.","image":"https://static.wikia.nocookie.net/tmnt/images/f/f6/April1shot.jpg/revision/latest?cb=20140419161138"},{"name":"Bebop","rarity":"uncommon","id":"bebop","subtitle":"Villain","details":"A street punk mutated into a warthog, Bebop pairs brute strength with total loyalty to Shredder — and almost no common sense at all.","image":"https://static.wikia.nocookie.net/tmnt/images/3/3d/Bebop_%28IDW%29.jpg/revision/latest?cb=20131007163957"},{"name":"Faith Herbert","rarity":"uncommon","id":"faith-herbert","subtitle":"Hero","details":"Zephyr: a lifelong geek whose psionic flight powers make her Valiant's most joyful hero, a Harbinger renegade with an unshakable moral compass.","image":"https://static.wikia.nocookie.net/valiantcomics/images/2/2b/Faith_Vol_1_1.jpg/revision/latest?cb=20170802120823"},{"name":"Green Hornet","rarity":"uncommon","id":"green-hornet","subtitle":"Hero","details":"Newspaper publisher Britt Reid poses as a criminal by night, hunting the underworld from inside as the masked Green Hornet with Kato at his side.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f4/Green_Hornet_Comics_10.jpg"},{"name":"Jason Lee Scott (Red Ranger)","rarity":"uncommon","id":"jason-lee-scott-red-ranger","subtitle":"Hero","details":"The original Red Ranger and first leader of the Mighty Morphin team, Jason Lee Scott wields the Tyrannosaurus power and the Power Sword.","image":"https://static.wikia.nocookie.net/powerrangers/images/0/0a/MMPR_50_Red_Ranger.png/revision/latest?cb=20251110061713"},{"name":"Kick-Ass","rarity":"uncommon","id":"kick-ass","subtitle":"Hero","details":"Dave Lizewski is an ordinary teen with no powers who buys a wetsuit, calls himself Kick-Ass, and becomes a very real, very bruised vigilante.","image":"https://static.wikia.nocookie.net/kick-ass/images/f/fb/Kick-Ass_019.jpg/revision/latest?cb=20120904020720"},{"name":"Klaus Hargreeves","rarity":"uncommon","id":"klaus-hargreeves","subtitle":"Hero","details":"The Séance: Klaus can speak with — and be haunted by — the dead, a gift he numbs with drugs and dark humor in Gerard Way's Umbrella Academy.","image":"https://static.wikia.nocookie.net/umbrellaacademy/images/c/ca/Seance_Hail_Satan.png/revision/latest?cb=20200712232117"},{"name":"Krang","rarity":"uncommon","id":"krang","subtitle":"Villain","details":"A brain-like alien warlord from Dimension X who pilots a hulking android body and plots Earth's conquest alongside Shredder and the Technodrome.","image":"https://upload.wikimedia.org/wikipedia/en/6/6f/Krang_%28Teenage_Mutant_Ninja_Turtles%29.png"},{"name":"Liz Sherman","rarity":"uncommon","id":"liz-sherman","subtitle":"Hero","details":"A pyrokinetic B.P.R.D. agent whose uncontrolled childhood fire killed her family, Liz Sherman fights to master the flames she fears most.","image":"https://static.wikia.nocookie.net/hellboy/images/6/68/Liz_cover.jpg/revision/latest?cb=20191102205627"},{"name":"Lord Zedd","rarity":"uncommon","id":"lord-zedd","subtitle":"Villain","details":"The Emperor of Evil whose arrival eclipses Rita Repulsa, Lord Zedd creates monsters from ordinary objects and seeks the Rangers' total destruction.","image":"https://static.wikia.nocookie.net/powerrangers/images/1/16/LordZedd_BoomComics.jpg/revision/latest?cb=20230327233510"},{"name":"Ninjak","rarity":"uncommon","id":"ninjak","subtitle":"Hero","details":"Colin King, MI6's master spy and martial artist, blends ninja training with cutting-edge tech as Valiant's deadliest intelligence operative.","image":"https://upload.wikimedia.org/wikipedia/en/7/75/Ninjak_by_Mico_Suayan.jpg"},{"name":"Number Five","rarity":"uncommon","id":"number-five","subtitle":"Hero","details":"A boy assassin who leaps through time, Number Five returns from an apocalyptic future trapped in his thirteen-year-old body in Dark Horse's series.","image":"https://static.wikia.nocookie.net/umbrellaacademy/images/4/4a/Number_Five_2008.jpg/revision/latest?cb=20250615125643"},{"name":"Rasputin","rarity":"uncommon","id":"rasputin","subtitle":"Villain","details":"The mad monk Grigori Rasputin, whose occult bargains summon Hellboy to Earth and who schemes across death itself to unleash the Ogdru Jahad.","image":"https://static.wikia.nocookie.net/hellboy/images/f/fd/Rasputin-SoD.jpg/revision/latest?cb=20211210090304"},{"name":"Rex Splode","rarity":"uncommon","id":"rex-splode","subtitle":"Hero","details":"A brash Teen Team hero who charges objects with explosive energy and detonates them, masking a rough upbringing with nonstop bravado.","image":"https://static.wikia.nocookie.net/imagecomics/images/0/07/Invincible_TPB_%28New_Edition%29_Vol_7.jpg/revision/latest?cb=20250330152401"},{"name":"Robot","rarity":"uncommon","id":"robot","subtitle":"Anti-Hero","details":"A genius inventor whose frail real body stays hidden while his robotic drones lead the Teen Team and Guardians in Image's Invincible.","image":"https://static.wikia.nocookie.net/imagecomics/images/a/af/Rudolph_Conners_%28Invincible%29_001.jpg/revision/latest?cb=20190316175830"},{"name":"Rocksteady","rarity":"uncommon","id":"rocksteady","subtitle":"Villain","details":"Mutated into a hulking rhino, Rocksteady is Bebop's partner in mayhem: a dim but devastating Foot Clan enforcer who loves breaking things.","image":"https://static.wikia.nocookie.net/tmnt/images/3/3f/Rocksteady_%28IDW%29.jpg/revision/latest?cb=20131007163913"},{"name":"The Darkness","rarity":"uncommon","id":"the-darkness","subtitle":"Anti-Hero","details":"Mafia hitman Jackie Estacado inherits the Darkness on his 21st birthday, commanding shadow demons and darkness-born weapons in Top Cow's series.","image":"https://upload.wikimedia.org/wikipedia/en/e/e5/TheDarkness.jpg"},{"name":"The Immortal","rarity":"uncommon","id":"the-immortal","subtitle":"Hero","details":"A warrior cursed with endless life and resurrection across thousands of years, serving as Abraham Lincoln and a Guardian of the Globe.","image":"https://static.wikia.nocookie.net/imagecomics/images/b/b2/Invincible_Universe_Vol_1_6_001.jpg/revision/latest?cb=20150712190848"},{"name":"The Tick","rarity":"uncommon","id":"the-tick","subtitle":"Hero","details":"A nigh-invulnerable, gleefully absurd hero in a blue tick suit, Ben Edlund's creation protects The City with mighty leaps and mighty non sequiturs.","image":"https://upload.wikimedia.org/wikipedia/en/f/f7/Tick_%28New_England_Comics_character%29.png"},{"name":"Usagi Yojimbo","rarity":"uncommon","id":"usagi-yojimbo","subtitle":"Hero","details":"Miyamoto Usagi, a masterless rabbit ronin, wanders a feudal Japan of animal samurai in Stan Sakai's long-running, meticulously crafted series.","image":"https://upload.wikimedia.org/wikipedia/en/0/03/Usagi_Yojimbo_The_Ronin.jpg"},{"name":"Witchblade","rarity":"uncommon","id":"witchblade","subtitle":"Hero","details":"NYPD detective Sara Pezzini bonds with the Witchblade, a sentient metal gauntlet forming armor and blades — Top Cow's flagship heroine.","image":"https://static.wikia.nocookie.net/imagecomics/images/3/34/Witchblade_Vol_1_10.jpg/revision/latest?cb=20140521165414"}]});
